"""pyarrow.dataset — iOS shim (Arrow Datasets C++ component not built).

datasets' parquet/folder_based packaged builders `import pyarrow.dataset as
ds` at module level (and datasets imports all builders at `import datasets`),
but only use `ds.*` when loading parquet/folder datasets. This shim makes the
import succeed so JSON/CSV/from_dict/from_pandas/map/split work; loading a
parquet or folder-based dataset raises a clear error. Real Arrow Datasets need
pyarrow rebuilt with ARROW_DATASET=ON.
"""
_MSG = ("pyarrow on iOS was built without the Arrow Datasets component. "
        "In-memory (from_dict/from_pandas), JSON/CSV load_dataset, and "
        ".map/.filter/.train_test_split work; parquet/folder-based datasets "
        "do not. Rebuild pyarrow with ARROW_DATASET=ON for full support.")
class _NoDataset(RuntimeError):
    def __init__(self, *a, **k): super().__init__(_MSG)
def _unavailable(*_a, **_k): raise _NoDataset()
class Dataset:
    def __init__(self, *a, **k): raise _NoDataset()
class FileSystemDataset:
    def __init__(self, *a, **k): raise _NoDataset()
class Scanner:
    def __init__(self, *a, **k): raise _NoDataset()
    @staticmethod
    def from_dataset(*a, **k): raise _NoDataset()
class ParquetFileFormat:
    def __init__(self, *a, **k): raise _NoDataset()
class CsvFileFormat:
    def __init__(self, *a, **k): raise _NoDataset()
class FileFormat:
    def __init__(self, *a, **k): raise _NoDataset()
class Partitioning:
    def __init__(self, *a, **k): raise _NoDataset()
dataset = _unavailable
partitioning = _unavailable
field = _unavailable
scalar = _unavailable
def __getattr__(name):
    if name.startswith("_"): raise AttributeError(name)
    return _unavailable
